export type CheckInGorunumu = CheckIn & { kullaniciAdi: string }

type CheckInSatiriProfilli = CheckInSatiri & { profiller: { ad: string } }

function satiriGorunumeCevir(satir: CheckInSatiriProfilli): CheckInGorunumu {
  return { ...satiriCheckInACevir(satir), kullaniciAdi: satir.profiller.ad }
}

export async function suAnBurdakileriGetir(mekanId: string): Promise<CheckInGorunumu[]> {
  const { data, error } = await supabase
    .from('check_inler')
    .select('id, mekan_id, not_metni, fotograf, olusturma_zamani, bitis_zamani, konum, profiller(ad)')
    .not('konum', 'is', null)
    .eq('mekan_id', mekanId)
  if (error) throw new Error(error.message)
  return (data as unknown as CheckInSatiriProfilli[]).map(satiriGorunumeCevir)
}

export async function mekanAnilariniGetir(mekanId: string): Promise<CheckInGorunumu[]> {
  const { data, error } = await supabase
    .from('check_inler')
    .select('id, mekan_id, not_metni, fotograf, olusturma_zamani, bitis_zamani, konum, profiller(ad)')
    .is('konum', null)
    .eq('mekan_id', mekanId)
  if (error) throw new Error(error.message)
  return (data as unknown as CheckInSatiriProfilli[]).map(satiriGorunumeCevir)
}
